sql.where:
s.s_active IN (1, 2)

    AND s.s_type = #{spaceVO.type_filter}


    AND s.s_active = #{spaceVO.active_filter}


    AND s.s_name LIKE CONCAT('%', #{spaceVO.search_word}, '%')

mapper.update:
UPDATE space
   SET b_idx          = #{b_idx},
       s_name         = #{s_name},
       s_type         = #{s_type},
       s_price        = #{s_price},
       s_max_capacity = #{s_max_capacity},
       s_description  = #{s_description}
       , s_img = #{s_img}
 WHERE s_idx = #{s_idx}

UPDATE space
   SET s_active = #{s_active}
 WHERE s_idx = #{s_idx}

UPDATE space
   SET s_active = 1
 WHERE s_idx = #{s_idx}
